const docks=['left','right','top','bottom'];
const storageKey='plane-workspace-panels-v3';
const clamp=(value,min,max)=>Math.max(min,Math.min(max,value));
const copy=value=>JSON.parse(JSON.stringify(value));

export const toolHasProperties=tool=>['select','text','arrow','pen','shape'].includes(tool);

export function revealPanelState(state){return {...state,visible:true,collapsed:false};}

export function defaultPanelStates(width=1200,height=800){const compact=width<720;return {
  layers:{mode:'dock',dock:'right',width:compact?Math.min(290,width*.86):310,height:Math.min(620,height*.78),x:Math.max(12,width-650),y:72,visible:false,collapsed:false},
  properties:{mode:'float',dock:'right',width:compact?Math.min(290,width*.86):310,height:Math.min(610,height-110),x:Math.max(12,width-650),y:72,visible:false,collapsed:false}
};}

export function normalizePanelState(value,fallback,bounds={width:1200,height:800}){const state={...fallback,...value};state.mode=state.mode==='float'?'float':'dock';state.dock=docks.includes(state.dock)?state.dock:fallback.dock;state.width=clamp(Number(state.width)||fallback.width,240,Math.max(240,bounds.width*.72));state.height=clamp(Number(state.height)||fallback.height,180,Math.max(180,bounds.height*.82));state.x=clamp(Number(state.x)||0,8,Math.max(8,bounds.width-state.width-8));state.y=clamp(Number(state.y)||0,8,Math.max(8,bounds.height-state.height-8));state.visible=state.visible!==false;state.collapsed=Boolean(state.collapsed);return state;}

function readSaved(){try{const value=JSON.parse(localStorage.getItem(storageKey)||'null');return value&&typeof value==='object'?value:{};}catch{return {};}}

export function initPanelWorkspace({workspace,panels,resetButton}){const rect=()=>workspace.getBoundingClientRect(),defaults=defaultPanelStates(rect().width,rect().height),saved=readSaved(),states={};for(const item of panels)states[item.id]=normalizePanelState(saved[item.id],defaults[item.id],rect());let topZ=20,activeMenu=null;
  const persist=()=>localStorage.setItem(storageKey,JSON.stringify(states));
  const updateToggles=()=>{for(const item of panels){const visible=states[item.id].visible;item.toggle?.setAttribute('aria-expanded',String(visible));item.toggle?.classList.toggle('active-panel',visible);}};
  const closeMenus=()=>{for(const item of panels)item.element.classList.remove('panel-menu-open');activeMenu=null;};
  const apply=()=>{const bounds=rect(),offsets={left:0,right:0,top:0,bottom:0};for(const item of panels){const state=states[item.id],panel=item.element;Object.assign(state,normalizePanelState(state,defaults[item.id],bounds));panel.hidden=!state.visible;panel.dataset.panelMode=state.mode;panel.dataset.panelDock=state.dock;panel.classList.toggle('panel-collapsed',state.collapsed);panel.querySelector('[data-panel-collapse]')?.setAttribute('aria-expanded',String(!state.collapsed));panel.style.zIndex=String(state.mode==='float'?Math.max(21,Number(panel.style.zIndex)||21):18);if(!state.visible)continue;if(state.mode==='dock'){const vertical=['left','right'].includes(state.dock),size=state.collapsed?50:vertical?state.width:state.height;panel.style.left=state.dock==='left'?offsets.left+'px':state.dock==='right'?'auto':'0';panel.style.right=state.dock==='right'?offsets.right+'px':state.dock==='left'?'auto':'0';panel.style.top=state.dock==='top'?offsets.top+'px':state.dock==='bottom'?'auto':'0';panel.style.bottom=state.dock==='bottom'?offsets.bottom+'px':state.dock==='top'?'auto':'0';panel.style.width=vertical?size+'px':'auto';panel.style.height=vertical?'auto':size+'px';offsets[state.dock]+=size;}else{panel.style.left=state.x+'px';panel.style.top=state.y+'px';panel.style.right='auto';panel.style.bottom='auto';panel.style.width=state.width+'px';panel.style.height=state.collapsed?'44px':state.height+'px';}}
    workspace.style.setProperty('--dock-left',offsets.left+'px');workspace.style.setProperty('--dock-right',offsets.right+'px');workspace.style.setProperty('--dock-top',offsets.top+'px');workspace.style.setProperty('--dock-bottom',offsets.bottom+'px');updateToggles();};
  const setDock=(id,dock)=>{const state=states[id];state.mode='dock';state.dock=docks.includes(dock)?dock:'right';state.collapsed=false;closeMenus();apply();persist();};
  const setFloat=(id,fromRect)=>{const bounds=rect(),state=states[id];state.mode='float';state.width=clamp(fromRect?.width||state.width,240,bounds.width*.72);state.height=clamp(fromRect?.height||state.height,180,bounds.height*.82);state.x=clamp((fromRect?.left??bounds.left+state.x)-bounds.left,8,Math.max(8,bounds.width-state.width-8));state.y=clamp((fromRect?.top??bounds.top+state.y)-bounds.top,8,Math.max(8,bounds.height-state.height-8));state.collapsed=false;apply();persist();};
  const show=id=>{states[id].visible=true;apply();persist();};
  const hide=id=>{states[id].visible=false;closeMenus();apply();persist();};
  const toggle=id=>states[id].visible?hide(id):show(id);
  const bringFront=panel=>{if(panel.dataset.panelMode==='float')panel.style.zIndex=String(++topZ);};
  const reveal=id=>{const item=panels.find(panel=>panel.id===id);Object.assign(states[id],revealPanelState(states[id]));closeMenus();apply();if(item)bringFront(item.element);persist();};
  for(const item of panels){const {id,element:panel,handle,toggle:toggleButton}=item,state=states[id],resize=panel.querySelector('[data-panel-resize]');
    toggleButton?.addEventListener('click',()=>toggle(id));panel.addEventListener('pointerdown',()=>bringFront(panel));
    panel.addEventListener('click',event=>{const dock=event.target.closest('[data-panel-dock]')?.dataset.panelDock;if(dock){setDock(id,dock);return}if(event.target.closest('[data-panel-float]')){setFloat(id,panel.getBoundingClientRect());return}if(event.target.closest('[data-panel-close]')){hide(id);return}if(event.target.closest('[data-panel-collapse]')){state.collapsed=!state.collapsed;closeMenus();apply();persist();return}if(event.target.closest('[data-panel-menu]')){const opening=activeMenu!==id;closeMenus();if(opening){panel.classList.add('panel-menu-open');activeMenu=id;}}});
    handle.addEventListener('dblclick',event=>{if(event.target.closest('button'))return;state.collapsed=!state.collapsed;apply();persist();});
    handle.addEventListener('pointerdown',event=>{if(event.button!==0||event.target.closest('button,input,.panel-dock-menu'))return;event.preventDefault();closeMenus();bringFront(panel);const bounds=rect(),startRect=panel.getBoundingClientRect(),start={x:event.clientX,y:event.clientY,mode:state.mode},pointerId=event.pointerId;handle.setPointerCapture(pointerId);panel.classList.add('panel-dragging');const move=e=>{const dx=e.clientX-start.x,dy=e.clientY-start.y;if(start.mode==='dock'&&state.mode==='dock'&&Math.hypot(dx,dy)>6)setFloat(id,startRect);if(state.mode==='float'){state.x=clamp(startRect.left-bounds.left+dx,8,Math.max(8,bounds.width-state.width-8));state.y=clamp(startRect.top-bounds.top+dy,8,Math.max(8,bounds.height-(state.collapsed?44:state.height)-8));apply();}const edge=e.clientX-bounds.left<42?'left':bounds.right-e.clientX<42?'right':e.clientY-bounds.top<42?'top':bounds.bottom-e.clientY<42?'bottom':'';workspace.dataset.dockPreview=edge;};const up=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',up);panel.classList.remove('panel-dragging');const edge=workspace.dataset.dockPreview;delete workspace.dataset.dockPreview;if(edge)setDock(id,edge);else{apply();persist();}};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',up);});
    resize?.addEventListener('pointerdown',event=>{if(event.button!==0)return;event.preventDefault();bringFront(panel);const start={x:event.clientX,y:event.clientY,width:state.width,height:state.height};resize.setPointerCapture(event.pointerId);panel.classList.add('panel-resizing');const move=e=>{const bounds=rect(),dx=e.clientX-start.x,dy=e.clientY-start.y;if(state.mode==='float'){state.width=clamp(start.width+dx,240,Math.max(240,bounds.width-state.x-8));state.height=clamp(start.height+dy,180,Math.max(180,bounds.height-state.y-8));}else if(state.dock==='left')state.width=clamp(start.width+dx,240,bounds.width*.72);else if(state.dock==='right')state.width=clamp(start.width-dx,240,bounds.width*.72);else if(state.dock==='top')state.height=clamp(start.height+dy,180,bounds.height*.72);else state.height=clamp(start.height-dy,180,bounds.height*.72);apply();};const up=()=>{resize.removeEventListener('pointermove',move);resize.removeEventListener('pointerup',up);panel.classList.remove('panel-resizing');persist();};resize.addEventListener('pointermove',move);resize.addEventListener('pointerup',up);});
  }
  document.addEventListener('pointerdown',event=>{if(activeMenu&&!event.target.closest('.panel-actions,.panel-dock-menu'))closeMenus();});
  resetButton?.addEventListener('click',()=>{const fresh=defaultPanelStates(rect().width,rect().height);for(const id of Object.keys(states))states[id]=copy(fresh[id]);localStorage.removeItem(storageKey);apply();persist();});
  window.addEventListener('resize',apply);apply();return {show,hide,toggle,reveal,setDock,setFloat,reset:()=>resetButton?.click(),state:id=>copy(states[id])};
}
